registerDiagram({
  id: 'sec-oidc-state-nonce-pkce',
  roadmap: 'security', module: 6, topic: 'state, nonce and PKCE; Flows for SPA, Mobile and Server Apps',
  kind: 'sequence',
  title: 'Three attacks, three random values: state, PKCE, nonce',
  desc: 'state is checked by the client on the redirect, the PKCE verifier by the provider at the token endpoint, and nonce by the client inside the signed ID token. Each one breaks a different attack.',
  actors: [
    { id: 'atk', label: 'Attacker', sub: 'own account, own app', icon: '😈', color: 'red', info: 'Has a normal account at the provider, can lure the victim to links and may control a malicious app on the victim phone.' },
    { id: 'br', label: 'Victim browser', sub: 'session at the RP', icon: '🌐', color: 'blue', info: 'Holds the RP session cookie, which is where the RP keeps the pending state, nonce and code_verifier for a login in progress.' },
    { id: 'rp', label: 'RP (client)', sub: 'your app', icon: '💻', color: 'green', info: 'Generates state, nonce and the PKCE verifier per login attempt, binds them to the browser session and checks them.' },
    { id: 'op', label: 'OpenID Provider', sub: 'authorize + token', icon: '🔐', color: 'purple', info: 'Stores the code_challenge with each code and echoes the nonce into the ID token it signs.' },
  ],
  steps: [
    { section: 'state stops login CSRF' },
    { from: 'atk', to: 'op', label: 'log in as attacker, keep code_A', caption: 'The attacker starts a login with their own account and stops before the callback, keeping a valid code_A.' },
    { from: 'atk', to: 'br', label: 'lure /callback?code=A', caption: 'The victim is tricked into opening the RP callback URL with the attacker code.' },
    { from: 'br', to: 'rp', label: 'GET /callback?code=A', caption: 'Without checks, the RP would redeem code_A and silently log the victim into the attacker account, where the victim might then save card details or documents.' },
    { from: 'rp', to: 'rp', label: 'state mismatch', caption: 'The victim session has no pending login with this state, so the RP rejects it. PKCE would also fail here: the victim session holds no verifier matching code_A.' },
    { section: 'PKCE stops code interception' },
    { from: 'br', to: 'op', label: 'authorize (S256 challenge)', caption: 'The victim now logs in for real. Only the hash of the verifier travels through the browser.' },
    { from: 'op', to: 'br', label: 'redirect: code_V', reply: true, caption: 'The provider returns code_V in the redirect URL.' },
    { from: 'atk', to: 'atk', label: 'steal code_V', caption: 'A malicious app registered for the same custom URL scheme, a log, a Referer header or an open redirect leaks code_V.' },
    { from: 'atk', to: 'op', label: 'POST /token code_V (no verifier)', caption: 'The attacker tries to redeem the stolen code at the token endpoint.' },
    { from: 'op', to: 'atk', label: 'invalid_grant', reply: true, caption: 'Missing or wrong code_verifier: SHA-256 of it does not match the stored challenge. Only the RP that created the challenge holds the verifier.' },
    { section: 'nonce stops ID token injection' },
    { from: 'atk', to: 'br', label: 'inject old ID token', caption: 'The attacker replays an ID token issued for a different login, for example one captured earlier, hoping the RP accepts it as proof of who logged in.' },
    { from: 'br', to: 'rp', label: 'id_token (nonce=X)', caption: 'The signature is genuine, because the provider really did sign this token for this client.' },
    { from: 'rp', to: 'rp', label: 'nonce mismatch', caption: 'The nonce claim must equal the nonce stored for this pending login and is single-use. A token minted for any other login fails, even with a valid signature.' },
  ],
});

registerDiagram({
  id: 'sec-oidc-discovery',
  roadmap: 'security', module: 6, topic: 'Discovery, JWKS and the UserInfo Endpoint',
  kind: 'sequence',
  title: 'OIDC discovery, JWKS, ID token validation and UserInfo',
  desc: 'The relying party learns every endpoint and key from the issuer discovery document, validates the ID token with keys from jwks_uri, and refetches keys when it sees an unknown kid.',
  actors: [
    { id: 'rp', label: 'Relying party', sub: 'your app (go-oidc)', icon: '💻', color: 'green', info: 'Configured with just the issuer URL, client_id and client credentials. Everything else comes from discovery.' },
    { id: 'br', label: 'Browser', sub: 'user agent', icon: '🌐', color: 'blue', info: 'Front channel only: the authorization request and the redirect back with the code.' },
    { id: 'op', label: 'OpenID Provider', sub: 'issuer', icon: '🔐', color: 'purple', info: 'For example https://login.example.com or a per-tenant Entra ID issuer such as https://login.microsoftonline.com/{tid}/v2.0.' },
  ],
  steps: [
    { section: 'At startup' },
    { from: 'rp', to: 'op', label: 'GET /.well-known/openid-configuration', caption: 'The RP fetches the discovery document from the configured issuer over HTTPS.' },
    { from: 'op', to: 'rp', label: 'issuer, endpoints, jwks_uri, algs', reply: true, caption: 'It lists issuer, authorization_endpoint, token_endpoint, userinfo_endpoint, jwks_uri, end_session_endpoint, supported signing algorithms and code_challenge_methods_supported.' },
    { from: 'rp', to: 'rp', label: 'check issuer', caption: 'The issuer in the document must equal the configured issuer exactly. This stops a hijacked or wrong document from redirecting trust to another issuer.' },
    { from: 'rp', to: 'op', label: 'GET jwks_uri', caption: 'Fetch the public signing keys.' },
    { from: 'op', to: 'rp', label: 'JWKS: keys k1, k2', reply: true, caption: 'Each JWK has a kid, key type and algorithm. The RP caches them.' },
    { section: 'Login (code + PKCE)' },
    { from: 'br', to: 'op', label: 'authorize + login', caption: 'The browser goes to the authorization_endpoint with scope=openid, state, nonce and the PKCE challenge, and the user signs in.' },
    { from: 'op', to: 'br', label: 'code + state', reply: true, caption: 'Redirect back with a single-use code.' },
    { from: 'br', to: 'rp', label: 'callback: code, state', caption: 'The RP checks state against the session.' },
    { from: 'rp', to: 'op', label: 'POST token_endpoint (code, verifier)', caption: 'Back-channel token request with PKCE verifier and client authentication.' },
    { from: 'op', to: 'rp', label: 'id_token + access_token', reply: true, caption: 'The ID token is for the RP (aud = client_id); the access token is for APIs and UserInfo.' },
    { from: 'rp', to: 'rp', label: 'validate ID token', caption: 'Verify the signature with the JWKS key named by kid and the expected alg; iss exactly; aud contains client_id (azp if several audiences); exp and iat; nonce; auth_time and acr if requested. Key users on (iss, sub), never email.' },
    { section: 'Profile claims' },
    { from: 'rp', to: 'op', label: 'GET userinfo  Bearer AT', caption: 'Fetch fresher or extra claims (name, picture, email) that are kept out of the ID token to keep it small.' },
    { from: 'op', to: 'rp', label: '{ sub, email, name }', reply: true, caption: 'UserInfo returns claims about the user who authorized the access token.' },
    { from: 'rp', to: 'rp', label: 'same sub?', caption: 'The UserInfo sub must equal the ID token sub, otherwise reject: it is a token substitution. Never authorize on mutable claims like email or name.' },
    { section: 'Later: the provider rotates keys' },
    { from: 'rp', to: 'rp', label: 'unknown kid k3', caption: 'A new ID token names kid k3, which is not in the cache, because the provider published a new key and started signing with it.' },
    { from: 'rp', to: 'op', label: 'GET jwks_uri (refresh)', caption: 'Refetch the JWKS on an unknown kid, but rate-limit it: random kids from an attacker must not turn your RP into a load generator against the provider.' },
    { from: 'op', to: 'rp', label: 'JWKS: keys k2, k3', reply: true, caption: 'k3 is found and validation proceeds. Rotation is invisible to well-behaved RPs because the provider publishes new keys before signing with them.' },
  ],
});

