registerDiagram({
  id: 'sec-saml-sp-initiated',
  roadmap: 'security', module: 7, topic: 'SP-Initiated vs IdP-Initiated Flows',
  kind: 'sequence',
  title: 'SAML 2.0 Web SSO: SP-initiated, then IdP-initiated',
  desc: 'SP and IdP never talk directly during login: the browser carries the AuthnRequest by redirect and the signed Response by auto-POST. InResponseTo ties the response to a request the SP really made.',
  actors: [
    { id: 'sp', label: 'Service Provider', sub: 'app.example.com', color: 'green', info: 'Your SaaS app. Knows the IdP entityID, SSO URL and signing certificate from metadata. Exposes an Assertion Consumer Service (ACS) URL.' },
    { id: 'br', label: 'Browser', sub: 'carries messages', icon: '🌐', color: 'blue', info: 'Transports SAML messages: HTTP-Redirect binding (query string) for the small AuthnRequest, HTTP-POST binding (auto-submitted form) for the large signed Response.' },
    { id: 'idp', label: 'Identity Provider', sub: 'Entra ID, Okta, ADFS', color: 'purple', info: 'Authenticates the user, applies conditional access and MFA, keeps the SSO session cookie on its own domain, and signs assertions with the key published in its metadata.' },
  ],
  steps: [
    { section: 'SP-initiated (preferred)' },
    { from: 'br', to: 'sp', label: 'GET /reports', caption: 'The user opens a deep link without a local session.' },
    { from: 'sp', to: 'sp', label: 'AuthnRequest', caption: 'The SP creates an AuthnRequest (ID _req-4c1e, Issuer = SP entityID, ACS URL), remembers the request ID as pending and single-use, and keeps the target /reports behind an opaque RelayState reference.' },
    { from: 'sp', to: 'br', label: '302 ?SAMLRequest=...', reply: true, caption: 'HTTP-Redirect binding: the request is DEFLATE-compressed and base64-encoded into the query string, optionally signed with SigAlg and Signature parameters.' },
    { from: 'br', to: 'idp', label: 'GET /sso?SAMLRequest', caption: 'The browser follows the redirect to the IdP SingleSignOnService endpoint.' },
    { from: 'idp', to: 'br', label: 'login + MFA', reply: true, caption: 'If the IdP already has a session cookie this step is skipped, which is exactly what makes it single sign-on. Conditional access policies (MFA, managed device) apply here.' },
    { from: 'br', to: 'idp', label: 'credentials / passkey', caption: 'The user authenticates only at the IdP. The SP never sees the password.' },
    { from: 'idp', to: 'idp', label: 'sign assertion', caption: 'The assertion holds NameID, Conditions (Audience = SP entityID, NotBefore, NotOnOrAfter), SubjectConfirmationData (Recipient = ACS, InResponseTo = _req-4c1e), AuthnStatement and attributes, signed with the IdP key.' },
    { from: 'idp', to: 'br', label: 'auto-POST form', reply: true, caption: 'HTTP-POST binding: an HTML form with SAMLResponse and RelayState submits itself to the ACS URL. POST is used because signed responses are too large for a URL.' },
    { from: 'br', to: 'sp', label: 'POST /acs (Response)', caption: 'The SP receives the base64-encoded SAMLResponse at its ACS endpoint.' },
    { from: 'sp', to: 'sp', label: 'validate response', caption: 'Verify the signature with the IdP certificate from metadata (never the embedded KeyInfo) and use only the signed element. Check Destination and Recipient, Audience, InResponseTo pending (then delete it), time window and assertion ID replay.' },
    { from: 'sp', to: 'br', label: '302 /reports + cookie', reply: true, caption: 'The SP maps NameID and attributes to a user, creates a fresh local session and redirects to the target it stored, not to an arbitrary URL from RelayState.' },
    { section: 'IdP-initiated (unsolicited)' },
    { from: 'br', to: 'idp', label: 'click app tile', caption: 'The user starts from the IdP portal (My Apps, Okta dashboard) instead of the SP.' },
    { from: 'idp', to: 'br', label: 'unsolicited Response', reply: true, caption: 'The IdP sends a signed response with no InResponseTo, because the SP never asked for it.' },
    { from: 'br', to: 'sp', label: 'POST /acs (no req)', caption: 'Nothing binds this assertion to a request from this browser: an attacker can push their own assertion (login CSRF) or replay a stolen one within its validity window.' },
    { from: 'sp', to: 'sp', label: 'bounce to SP-init', caption: 'Safest: disable IdP-initiated SSO, or treat it only as a hint and immediately start an SP-initiated flow. Otherwise require short validity, a strict assertion-ID replay cache and an allow-list for RelayState.' },
  ],
});

