registerDiagram({
  id: 'sec-zanzibar-check',
  roadmap: 'security', module: 8, topic: 'ReBAC and Google Zanzibar (OpenFGA, SpiceDB)',
  kind: 'graph',
  title: 'Zanzibar Check: walking relation tuples',
  desc: 'Permissions are derived from a graph of relation tuples (object#relation@subject). Check walks that graph using the schema rewrite rules. Press Play to answer "can Alice view doc 1?" and "can Bob?".',
  groups: [
    { id: 'tuples', label: 'Relation tuples', x: 0, y: 1, w: 7, h: 3, color: 'blue' },
  ],
  nodes: [
    { id: 'alice', label: 'user:alice', icon: '🧑', x: 0, y: 1, shape: 'pill', color: 'gray', info: 'A subject. Alice has no direct grant on doc:1; her access comes only through her group membership.' },
    { id: 'eng', label: 'group:eng', sub: 'member: alice', x: 2, y: 1, color: 'teal', info: 'Tuple group:eng#member@user:alice. Adding someone to the group is one tuple write and grants everything the group can reach.' },
    { id: 'folder', label: 'folder:x', sub: 'editor: eng#member', x: 4, y: 1, color: 'purple', info: 'Tuple folder:x#editor@group:eng#member: a userset subject meaning "every member of group eng". Schema: folder viewer = viewer + editor.' },
    { id: 'doc1', label: 'doc:1', sub: 'parent: folder:x', x: 6, y: 1, color: 'orange', info: 'Tuple doc:1#parent@folder:x. Schema: doc viewer = direct viewer + editor + viewer of parent. That last rewrite is what makes folder sharing inherit.' },
    { id: 'bob', label: 'user:bob', icon: '🧑', x: 0, y: 3, shape: 'pill', color: 'gray', info: 'Bob is a direct viewer of doc:2 and nothing else.' },
    { id: 'doc2', label: 'doc:2', sub: 'viewer: bob', x: 2, y: 3, color: 'orange', info: 'Tuple doc:2#viewer@user:bob: a direct grant.' },
    { id: 'check', label: 'Check API', sub: 'OpenFGA / SpiceDB', x: 2, y: 5, shape: 'pill', color: 'blue', info: 'The authorization service. APIs: Check, Expand, ListObjects, ListUsers, Write. A critical, latency-sensitive dependency: run it highly available and close to the app.' },
    { id: 'app', label: 'Docs app', sub: 'writes + checks', x: 4, y: 5, color: 'green', info: 'Writes tuples whenever relationships change (share, move, group membership), ideally through an outbox so tuples never drift from the primary database. Calls Check on every request.' },
  ],
  edges: [
    { from: 'alice', to: 'eng', label: 'member' },
    { from: 'eng', to: 'folder', label: 'editor' },
    { from: 'folder', to: 'doc1', label: 'parent of' },
    { from: 'bob', to: 'doc2', label: 'viewer' },
    { from: 'app', to: 'check', label: 'Check / Write' },
  ],
  steps: [
    { caption: 'The data is a set of tuples: alice is a member of group eng, members of eng are editors of folder x, folder x is the parent of doc 1, and bob is a viewer of doc 2.', active: ['alice>eng', 'eng>folder', 'folder>doc1', 'bob>doc2', 'tuples'] },
    { caption: 'The schema adds rewrite rules: doc viewer = direct viewers OR editors OR viewers of the parent folder; folder viewer = viewers OR editors. Permissions are computed, never stored per user.', active: ['doc1', 'folder'] },
    { caption: 'A request arrives: can Alice view doc 1? The app asks Check(doc:1#viewer@user:alice).', flows: [{ from: 'app', to: 'check', label: 'doc:1#viewer@alice' }] },
    { caption: 'doc:1 has no direct viewer tuple for Alice, so Check follows the parent rewrite to folder:x and asks whether Alice is a viewer there.', flows: [{ from: 'check', to: 'doc1', label: 'direct viewer?' }, { from: 'doc1', to: 'folder', label: 'parent viewer?' }] },
    { caption: 'folder:x viewers include its editors, which are the members of group:eng, and Alice is a member. A path exists, so the answer is allowed.', flows: [{ from: 'folder', to: 'eng', label: 'editors = eng' }, { from: 'eng', to: 'alice', label: 'member', color: 'green' }] },
    { caption: 'Can Bob view doc 1? No path leads from doc:1 to Bob; his only tuple grants doc:2. Denied. Deny is the default when the graph has no path.', flows: [{ from: 'app', to: 'check', label: 'doc:1#viewer@bob' }, { from: 'check', to: 'doc1', label: 'no path', color: 'red' }], active: ['bob', 'doc2'] },
    { caption: 'For list pages use ListObjects (which docs can Alice view?) instead of filtering with thousands of Checks. Reverse questions like "who can see this?" are also answerable, unlike with ABAC.', flows: [{ from: 'check', to: 'app', label: 'doc:1, doc:9' }] },
    { caption: 'The new enemy problem: Alice removes Bob from a folder and then adds a secret doc; a stale replica must not show it to Bob. Writes return a zookie (SpiceDB ZedToken) that later Checks pass to demand a snapshot at least that fresh.', flows: [{ from: 'app', to: 'check', label: 'write -> zookie' }] },
  ],
});

