registerDiagram({
  id: 'sec-envelope-encryption',
  roadmap: 'security', module: 9, topic: 'Envelope Encryption and Key Management Services',
  kind: 'graph',
  title: 'Envelope encryption with a KMS: DEKs wrapped by KEKs',
  desc: 'Data is encrypted locally with a data key (DEK); only the small DEK is encrypted by the key-encryption key (KEK) inside the KMS. The KEK never leaves the HSM, and every unwrap is authorized and audited.',
  groups: [
    { id: 'hsm', label: 'KMS (HSM)', x: 1.5, y: 3, w: 3.5, h: 2, color: 'purple' },
  ],
  nodes: [
    { id: 'data', label: 'Record', sub: 'PII to protect', x: 0, y: 1, shape: 'pill', color: 'gray', info: 'Any size: a database field, a file, a backup. Bulk data never travels to the KMS, so there is no size limit and no per-byte latency.' },
    { id: 'app', label: 'App', sub: 'AES-256-GCM locally', x: 2, y: 1, color: 'blue', info: 'Encrypts with the plaintext DEK using AES-256-GCM with a unique nonce and associated data (tenant id, record id), then wipes the DEK from memory. Libraries like Tink or the AWS Encryption SDK do this for you.' },
    { id: 'store', label: 'DB / S3', sub: 'blob + wrapped DEK', x: 4, y: 1, shape: 'db', color: 'teal', info: 'Stores ciphertext and the wrapped (encrypted) DEK side by side, plus the KEK id. A stolen copy contains only ciphertext and DEKs encrypted under a key the thief cannot use.' },
    { id: 'kms', label: 'KMS API', sub: 'IAM + key policy', x: 2, y: 3, color: 'purple', info: 'GenerateDataKey and Decrypt. Every call is authorized by IAM and the key policy (separate encrypt and decrypt roles), may require an encryption context, and is logged.' },
    { id: 'kek', label: 'KEK tenant t42', sub: 'never leaves the HSM', x: 4, y: 3, color: 'purple', info: 'Key-encryption key for one tenant. Rotation creates a new key version; old versions stay available for decrypting existing DEKs, so data is never re-encrypted in bulk.' },
    { id: 'kek2', label: 'KEK tenant t43', sub: 'own blast radius', x: 4, y: 4, color: 'purple', info: 'Per-tenant KEKs isolate tenants cryptographically and make crypto-shredding possible per tenant.' },
    { id: 'audit', label: 'Audit log', sub: 'CloudTrail', x: 0, y: 3, shape: 'db', color: 'orange', info: 'Every GenerateDataKey and Decrypt with caller, key and encryption context. Alert on unusual decrypt volume or on key disable and delete.' },
  ],
  edges: [
    { from: 'data', to: 'app', label: 'plaintext' },
    { from: 'app', to: 'store', both: true, label: 'ciphertext+wDEK' },
    { from: 'app', to: 'kms', both: true, label: 'DEK requests' },
    { from: 'kms', to: 'kek', label: 'wrap / unwrap' },
    { from: 'kms', to: 'kek2' },
    { from: 'kms', to: 'audit', label: 'every call' },
  ],
  steps: [
    { caption: 'The app calls GenerateDataKey for tenant t42 with an encryption context such as {tenant: t42, purpose: invoices}. The KMS returns a fresh DEK twice: in plaintext and wrapped under the tenant KEK.', flows: [{ from: 'app', to: 'kms', label: 'GenerateDataKey' }, { from: 'kms', to: 'app', label: 'DEK + wrapped DEK' }], active: ['kek'] },
    { caption: 'The record is encrypted locally with the plaintext DEK using AES-256-GCM, with the record and tenant ids as associated data. Then the plaintext DEK is wiped from memory.', flows: [{ from: 'data', to: 'app', label: 'record' }] },
    { caption: 'Ciphertext and wrapped DEK are stored together. A database dump or leaked backup is useless without permission to call KMS Decrypt.', flows: [{ from: 'app', to: 'store', label: 'ciphertext + wDEK' }] },
    { caption: 'To read: load both, send only the small wrapped DEK to KMS Decrypt. IAM and the encryption context must match; the KMS unwraps it inside the HSM and returns the DEK. Cache DEKs briefly to cut latency and cost.', flows: [{ from: 'store', to: 'app', label: 'ciphertext + wDEK' }, { from: 'app', to: 'kms', label: 'Decrypt(wDEK)' }, { from: 'kms', to: 'app', label: 'DEK' }] },
    { caption: 'Every unwrap is logged with who, which key and which context, so data access becomes auditable at the key level, and decrypt rights can be separated from database access.', flows: [{ from: 'kms', to: 'audit', label: 'Decrypt by svc-a' }] },
    { caption: 'Rotation: enable automatic KEK rotation. New DEKs are wrapped by the new version, old versions still unwrap old DEKs, and at most you rewrap DEKs. Terabytes of data are never re-encrypted.', active: ['kek', 'kms'] },
    { caption: 'Crypto-shredding: schedule deletion of tenant t42 KEK and every t42 DEK becomes unrecoverable, including copies in backups and replicas. Tenant t43 is untouched. Useful for GDPR erasure.', active: ['kek', 'store'] },
  ],
});

