registerDiagram({
  id: 'sec-x509-chain',
  roadmap: 'security', module: 10, topic: 'X.509 Certificates and the Chain of Trust',
  kind: 'graph',
  title: 'Chain of trust: how a client validates a certificate path',
  desc: 'The server sends its leaf and the intermediates; the client builds a path to a root it already trusts and checks every signature, validity period, constraint and the hostname. The root is never taken from the server.',
  groups: [
    { id: 'chain', label: 'Sent by server', x: 0.5, y: 2, w: 2, h: 3, color: 'blue' },
  ],
  nodes: [
    { id: 'root', label: 'Root CA', sub: 'self-signed, offline', x: 1, y: 0, color: 'purple', info: 'Self-signed; trusted only because it is pre-installed in trust stores. Kept offline in an HSM and used rarely, to sign intermediates. Lifetimes of 20+ years.' },
    { id: 'inter', label: 'Intermediate CA', sub: 'CA:TRUE, pathlen:0', x: 1, y: 2, color: 'blue', info: 'Does day-to-day issuance. Basic Constraints CA:TRUE with pathlen, optional Name Constraints. If compromised it can be revoked and replaced without touching any trust store.' },
    { id: 'leaf', label: 'api.example.com', sub: 'leaf, SAN + EKU', x: 1, y: 4, color: 'green', info: 'SAN: DNS:api.example.com (the CN is ignored by browsers and Go). EKU serverAuth, Key Usage digitalSignature, notBefore and notAfter, SCTs from Certificate Transparency logs.' },
    { id: 'server', label: 'Server', sub: 'holds the leaf key', x: 3, y: 4, color: 'green', info: 'Must send leaf + intermediates in order (not the root). A missing intermediate may go unnoticed in browsers and in Go on macOS or Windows (the OS verifier can fetch it via AIA), but breaks Go on Linux, curl with OpenSSL, Python and Java.' },
    { id: 'client', label: 'Go client', sub: 'crypto/x509 Verify', x: 5, y: 2, color: 'gray', info: 'On Linux, Go builds paths only from the certificates in the handshake plus its root pool and never fetches missing intermediates. On macOS and Windows with system roots it delegates to the OS verifier. Never set InsecureSkipVerify to work around a failure.' },
    { id: 'store', label: 'Trust store', sub: 'OS / ca-certificates', x: 5, y: 0, shape: 'db', color: 'purple', info: 'The set of roots the client trusts: the OS store, the browser root program, or the ca-certificates bundle baked into a container image (a classic gap in distroless or scratch images).' },
  ],
  edges: [
    { from: 'root', to: 'inter', label: 'signs' },
    { from: 'inter', to: 'leaf', label: 'signs' },
    { from: 'server', to: 'leaf', label: 'serves' },
    { from: 'server', to: 'client', label: 'Certificate msg' },
    { from: 'client', to: 'store', label: 'anchor?' },
    { from: 'store', to: 'root', dashed: true, label: 'contains this root' },
  ],
  steps: [
    { caption: 'During the TLS handshake the server sends its certificate chain: the leaf, then the intermediate. It does not send the root; a root supplied by the server would prove nothing.', flows: [{ from: 'server', to: 'client', label: 'leaf + inter' }], active: ['chain'] },
    { caption: 'The client checks the leaf itself: the hostname must match a SAN entry, the date must be within notBefore and notAfter, EKU must include serverAuth, and public certificates need valid SCTs.', active: ['leaf', 'client'] },
    { caption: 'The leaf signature must verify with the intermediate public key (matched by issuer name and AKI/SKI). The intermediate must have CA:TRUE, a fitting pathlen and any Name Constraints honored.', flows: [{ from: 'inter', to: 'leaf', label: 'signature ok' }] },
    { caption: 'The intermediate must in turn be signed by a root that is already in the client trust store. Trust is anchored locally, never in anything the server sent.', flows: [{ from: 'root', to: 'inter', label: 'signature ok' }, { from: 'client', to: 'store', label: 'root found' }] },
    { caption: 'Revocation is checked where configured (CRLs pushed by browsers; OCSP is now optional and Let\'s Encrypt dropped it), but the real answer is short lifetimes: public certificates drop to 47 days by 2029, internal mTLS certificates often live hours.', active: ['leaf', 'inter'] },
    { caption: 'Classic outage: the server forgets the intermediate. Browsers and Go on macOS or Windows (OS verifier, AIA fetch) may still pass, but Go in a Linux pod fails: certificate signed by unknown authority. Test from Linux and fix the server chain.', flows: [{ from: 'server', to: 'client', label: 'leaf only', color: 'red' }] },
    { caption: 'Why intermediates exist: the root stays offline and rarely used, while intermediates can be rotated or revoked without updating trust stores. Watch Certificate Transparency logs and set CAA records to limit who can issue for you.', active: ['root', 'inter', 'store'] },
  ],
});

registerDiagram({
  id: 'sec-tls-termination',
  roadmap: 'security', module: 10, topic: 'TLS Termination vs Passthrough, and Certificate Rotation',
  kind: 'graph',
  title: 'Edge termination vs re-encryption vs passthrough',
  desc: 'Where TLS ends decides what the load balancer can see and do, who holds private keys, and whether traffic inside your network is encrypted. Press Play to compare the three modes.',
  groups: [
    { id: 'l1', label: 'Edge termination', x: 0, y: 0, w: 7, h: 1, color: 'blue' },
    { id: 'l2', label: 'Re-encryption (bridging)', x: 0, y: 1.4, w: 7, h: 1, color: 'green' },
    { id: 'l3', label: 'Passthrough', x: 0, y: 2.8, w: 7, h: 1, color: 'orange' },
  ],
  nodes: [
    { id: 'c1', label: 'Client', icon: '💻', x: 0, y: 0, color: 'gray', info: 'Validates the public certificate presented by the load balancer.' },
    { id: 'lb1', label: 'Ingress / LB', sub: 'holds cert + key', x: 2, y: 0, color: 'blue', info: 'Decrypts, so it can route by path and header, run a WAF, cache and add X-Forwarded-For. Certificates are managed in one place, for example cert-manager with ACME.' },
    { id: 'b1', label: 'Pod', sub: 'plain HTTP', x: 4, y: 0, color: 'red', info: 'Receives plaintext. Acceptable only where the internal network is genuinely trusted or a mesh adds mTLS; zero trust says not to rely on the network.' },
    { id: 'c2', label: 'Client', icon: '💻', x: 0, y: 1.4, color: 'gray', info: 'Same experience for the client: it sees the public certificate on the load balancer.' },
    { id: 'lb2', label: 'Ingress / LB', sub: 'terminates, re-wraps', x: 2, y: 1.4, color: 'green', info: 'Terminates the client TLS, applies L7 features, then opens a new TLS (or mTLS) connection to the backend using certificates from an internal CA.' },
    { id: 'b2', label: 'Pod', sub: 'internal cert', x: 4, y: 1.4, color: 'green', info: 'Sees the load balancer as its TLS client. The real client identity must be forwarded in a trusted, sanitized header (for example X-Forwarded-Client-Cert) that is stripped from outside requests.' },
    { id: 'c3', label: 'Client', icon: '💻', x: 0, y: 2.8, color: 'gray', info: 'Its TLS session ends at the pod itself. Client certificates reach the backend directly.' },
    { id: 'lb3', label: 'L4 proxy', sub: 'routes by SNI only', x: 2, y: 2.8, color: 'orange', info: 'Never decrypts: it reads only the SNI in the ClientHello to pick a backend. No path routing, no WAF, no header injection.' },
    { id: 'b3', label: 'Pod', sub: 'cert + key, own mTLS', x: 4, y: 2.8, color: 'orange', info: 'Owns its certificate and key and can demand client certificates itself. Each backend must automate issuance, renewal and hot reload (tls.Config.GetCertificate).' },
    { id: 'v1', label: 'L7 features', sub: 'inside: plaintext', x: 6, y: 0, shape: 'pill', color: 'blue', info: 'Best edge features and simplest certificate management, but internal traffic is unencrypted and the load balancer holds the private keys.' },
    { id: 'v2', label: 'L7 + encrypted', sub: 'two sets of certs', x: 6, y: 1.4, shape: 'pill', color: 'green', info: 'Keeps L7 features and encrypts the internal hop. Costs a second TLS handshake per connection (pooled in practice) and an internal PKI.' },
    { id: 'v3', label: 'End-to-end TLS', sub: 'no L7 at the edge', x: 6, y: 2.8, shape: 'pill', color: 'orange', info: 'Strongest confidentiality and the backend sees client certificates directly. The edge is blind: no WAF, no path routing, no header injection.' },
  ],
  edges: [
    { from: 'c1', to: 'lb1', label: 'TLS (public cert)' },
    { from: 'lb1', to: 'b1', label: 'plain HTTP' },
    { from: 'c2', to: 'lb2', label: 'TLS (public cert)' },
    { from: 'lb2', to: 'b2', label: 'new TLS (internal)' },
    { from: 'c3', to: 'lb3', label: 'TLS, SNI visible' },
    { from: 'lb3', to: 'b3', label: 'same TLS stream' },
  ],
  steps: [
    { caption: 'Edge termination: TLS ends at the ingress or load balancer, which holds the public certificate and key. It sees plaintext HTTP, so it can do L7 routing, WAF, caching and header injection.', flows: [{ from: 'c1', to: 'lb1', label: 'TLS' }], active: ['l1', 'v1'] },
    { caption: 'The hop to the pod is plaintext. Fine on a truly trusted network, but anyone with a foothold inside can sniff or tamper, so most platforms add a mesh or re-encrypt.', flows: [{ from: 'lb1', to: 'b1', label: 'HTTP', color: 'red' }] },
    { caption: 'Re-encryption: terminate at the edge for L7 features, then open a new TLS or mTLS connection to the backend with an internal CA. Two sets of certificates to manage; the backend sees the load balancer as the client.', flows: [{ from: 'c2', to: 'lb2', label: 'TLS' }, { from: 'lb2', to: 'b2', label: 'new TLS' }], active: ['l2', 'v2'] },
    { caption: 'Passthrough: the L4 proxy never decrypts and routes on the SNI only. End-to-end encryption and the backend sees the client certificate, but there is no path routing or WAF at the edge, and every backend manages its own certificates.', flows: [{ from: 'c3', to: 'lb3', label: 'ClientHello' }, { from: 'lb3', to: 'b3', label: 'opaque bytes' }], active: ['l3', 'v3'] },
    { caption: 'Common Kubernetes pattern: edge termination with public certificates from cert-manager and ACME, plus mesh mTLS with short-lived internal certificates inside, which is re-encryption in effect. Use passthrough when the backend must see client certificates or compliance demands end-to-end TLS.', active: ['l1', 'l2', 'lb1', 'lb2', 'b2'] },
  ],
});

